import { useEffect, useState } from "react";
import { useRouter } from "next/router";
import Head from "next/head";
import { useSupabase } from "../contexts/AuthContext";

/**
 * Where Google (and the email-confirmation link) send the user back to.
 *
 * The exchange has to happen HERE, in the browser, because the PKCE code
 * verifier was generated by this browser when the flow started. A server route
 * would have the `code` and not the verifier, and Supabase would refuse it.
 *
 * Two shapes arrive at this page:
 *   ?code=...          — the PKCE authorization code flow (what we start).
 *   #access_token=...  — the older implicit flow, still used by some email
 *                        link templates. The client picks that up on its own
 *                        via detectSessionInUrl, so there is nothing to do but
 *                        wait for the session to appear.
 */
export default function SSOCallback() {
  const router = useRouter();
  const supabase = useSupabase();
  const [error, setError] = useState("");

  useEffect(() => {
    if (!router.isReady) return;

    const finish = async () => {
      const { code, error: oauthError, error_description: description } = router.query;

      // Google can also come back with a refusal — the user hit "Cancel", or
      // the app is not approved. Silently redirecting would look like a bug.
      if (oauthError) {
        setError(description || "Sign-in was cancelled or refused.");
        return;
      }

      if (code) {
        const { error: exchangeError } = await supabase.auth.exchangeCodeForSession(
          String(code)
        );
        if (exchangeError) {
          setError(exchangeError.message || "Could not complete sign-in.");
          return;
        }
      } else {
        // Implicit flow, or a link that has already been consumed.
        const { data } = await supabase.auth.getSession();
        if (!data.session) {
          setError("This sign-in link is no longer valid. Please try again.");
          return;
        }
      }

      const target = router.query.redirect_to;
      const safe =
        typeof target === "string" && target.startsWith("/") && !target.startsWith("//")
          ? target
          : "/post-auth";
      router.replace(safe);
    };

    finish();
  }, [router.isReady]);

  return (
    <>
      <Head>
        <title>Signing you in… — Vaulto</title>
      </Head>
      <div className="min-h-screen bg-[var(--bg)] flex flex-col items-center justify-center text-[var(--text)]">
        {error ? (
          <div className="text-center max-w-md w-full px-5">
            <div className="error-box">{error}</div>
            <button className="btn-secondary mt-2" onClick={() => router.replace("/auth")}>
              Back to sign in
            </button>
          </div>
        ) : (
          <div className="loading-box animate-pulse-glow">
            <div className="mb-6 flex justify-center logo">
              <span className="logo-mark">V</span><span>Vaulto</span>
            </div>
            <div className="spinner"></div>
            <p className="mt-4 text-[var(--muted)] text-sm tracking-wider uppercase font-semibold">
              Signing you in
            </p>
          </div>
        )}
      </div>
    </>
  );
}
